const vector = $json.data[0].embedding;
const literal = '[' + vector.join(',') + ']';
const sql = "SELECT p.numero_documento, p.primer_nombre, p.segundo_nombre, p.apellidos, p.fecha_nacimiento, 1 - (pe.embedding <=> '" + literal + "'::vector) AS similitud FROM persona_embeddings pe JOIN personas p ON p.numero_documento = pe.numero_documento ORDER BY pe.embedding <=> '" + literal + "'::vector LIMIT 5";
return [{ json: { sql } }];

const solicitud = $('Webhook').first().json.body;

const pregunta = solicitud.pregunta || '';
const sessionId = solicitud.session_id || '';
const usuarioId = solicitud.usuario_id || '';

if (
  typeof solicitud.pregunta !== 'string' ||
  !solicitud.pregunta.trim()
) {
  throw new Error('La pregunta no puede estar vacía');
}

const similares = $('Buscar similares')
  .all()
  .map(item => {
    const { similitud, ...persona } = item.json;
    return persona;
  });

const agregados = $('Agregados')
  .all()
  .map(item => item.json);

const masJoven =
  agregados.find(item => item.tipo === 'mas_joven') || null;

const masMayor =
  agregados.find(item => item.tipo === 'mas_mayor') || null;

const recordados = $('Recuperar persona recordada')
  .all()
  .map(item => item.json)
  .filter(item => item.numero_documento != null);

const personaRecordada = recordados[0] || null;

function nombreCompleto(persona) {
  if (!persona) return null;

  return [
    persona.primer_nombre,
    persona.segundo_nombre,
    persona.apellidos
  ].filter(Boolean).join(' ');
}

function normalizarTexto(texto) {
  return String(texto)
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/\s+/g, ' ')
    .trim();
}

const preguntaNormalizada = normalizarTexto(pregunta);

const consultaJoven =
  /\b(mas joven|menor edad|persona mas joven)\b/
    .test(preguntaNormalizada);

const consultaMayor =
  /\b(mas mayor|mayor edad|mas vieja|mas viejo|persona mayor)\b/
    .test(preguntaNormalizada);

const preguntaSeguimiento =
  /\b(y cuando|cuando nacio|fecha de nacimiento|cuantos anos|que edad|y donde|y cual|y su|de esa persona|de el|de ella)\b/
    .test(preguntaNormalizada);

let tipoConsulta = 'general';
let personaIdentificada = null;

if (consultaJoven && !consultaMayor) {
  tipoConsulta = 'mas_joven';
  personaIdentificada = masJoven;

} else if (consultaMayor && !consultaJoven) {
  tipoConsulta = 'mas_mayor';
  personaIdentificada = masMayor;

} else if (preguntaSeguimiento && personaRecordada) {
  tipoConsulta = 'seguimiento';
  personaIdentificada = personaRecordada;
}

const personaDocumento =
  personaIdentificada?.numero_documento != null
    ? String(personaIdentificada.numero_documento)
    : null;

const totalPersonas =
  agregados.length > 0 &&
  agregados[0].total_personas != null
    ? Number(agregados[0].total_personas)
    : null;

const datosContexto = {
  total_personas: totalPersonas,
  tipo_consulta: tipoConsulta,
  persona_identificada: personaIdentificada,
  persona_recordada: personaRecordada,
  persona_mas_joven: masJoven,
  persona_mas_mayor: masMayor,
  similares
};

const contexto = JSON.stringify(datosContexto, null, 2);

return [{
  json: {
    pregunta,
    sessionId,
    usuarioId,
    tipo_consulta: tipoConsulta,
    total_personas: totalPersonas,
    persona_documento: personaDocumento,
    contexto
  }
}];

