(() => {
  const datos = $('Armar contexto').first().json;
  const respuestaIA = $json.choices?.[0]?.message?.content || '';
  const contexto = JSON.parse(datos.contexto || '{}');

  const pregunta = String(datos.pregunta || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');

  const persona = contexto.persona_identificada;

  if (!persona || !persona.numero_documento) {
    return respuestaIA;
  }

  const nombre = [
    persona.primer_nombre,
    persona.segundo_nombre,
    persona.apellidos
  ].filter(Boolean).join(' ');

  // Respuesta exacta a preguntas sobre nacimiento.
  if (
    /cuando nacio|fecha de nacimiento|cuando nacio esa persona|en que fecha nacio/.test(pregunta)
  ) {
    if (!persona.fecha_nacimiento) {
      return `No tengo registrada la fecha de nacimiento de ${nombre}.`;
    }

    const fecha = String(persona.fecha_nacimiento).slice(0, 10);
    const partes = fecha.split('-').map(Number);

    const meses = [
      'enero', 'febrero', 'marzo', 'abril',
      'mayo', 'junio', 'julio', 'agosto',
      'septiembre', 'octubre', 'noviembre', 'diciembre'
    ];

    if (
      partes.length === 3 &&
      partes[1] >= 1 &&
      partes[1] <= 12
    ) {
      return `${nombre} nació el ${partes[2]} de ${meses[partes[1] - 1]} de ${partes[0]}.`;
    }
  }

  // Para las demás preguntas, conservar la respuesta de Ollama.
  return respuestaIA;
})()
}}

